-- Тема 13: варианты ответов выровнены по длине и форме (49 исправлений в 14 вопросах), ключи не меняются.
-- Источник: scripts/questions/080_option_length_topic13.js
-- Повторный запуск безопасен: вопрос и вариант ищутся по тексту, прежнее или уже новое значение допустимо,
-- иначе пакет отменяется. Ключи ответов, число и порядок вариантов не меняются.

BEGIN;
SET LOCAL standard_conforming_strings = on;
LOCK TABLE questions IN SHARE ROW EXCLUSIVE MODE;

DO $fix$
DECLARE fix record; matches integer; qid integer; k text;
BEGIN
    FOR fix IN SELECT * FROM (VALUES
        ('option', 'Как сервер просматривает строки pg_hba.conf?', 'Сверху вниз и использует первую подходящую строку', 'Сверху вниз, применяется первая подходящая строка', 'Поэтому частные правила располагают выше общих.', 'Сверху вниз; применяется первая подходящая строка, поэтому частные правила располагают выше общих.'),
        ('option', 'Как сервер просматривает строки pg_hba.conf?', 'Снизу вверх', 'Снизу вверх, применяется последняя подходящая строка', 'Просмотр идёт сверху вниз.', 'Просмотр идёт сверху вниз, а не снизу вверх.'),
        ('option', 'Как сервер просматривает строки pg_hba.conf?', 'Проверяет все строки и выбирает самую строгую', 'Проверяет все строки, выбирает самую строгую', 'Используется первая подходящая строка, а не самая строгая.', NULL),
        ('option', 'Как сервер просматривает строки pg_hba.conf?', 'В алфавитном порядке ролей', 'В алфавитном порядке имён ролей и баз', 'Порядок задаёт сам файл.', NULL),
        ('option', 'Подходящая строка в pg_hba.conf найдена, но аутентификация не прошла. Что дальше?', 'Проверяется следующая строка', 'Проверяется следующая строка файла', 'Следующие строки уже не проверяются.', NULL),
        ('option', 'Подходящая строка в pg_hba.conf найдена, но аутентификация не прошла. Что дальше?', 'Доступ запрещается, остальные строки не рассматриваются', 'Доступ отклоняется, остальные строки не читаются', 'Решение принимается по первой подходящей строке.', NULL),
        ('option', 'Подходящая строка в pg_hba.conf найдена, но аутентификация не прошла. Что дальше?', 'Разрешается доступ только на чтение', 'Доступ разрешается с ограниченными правами', 'При неудачной аутентификации подключение отклоняется, а не ограничивается чтением.', NULL),
        ('option', 'Как работает метод аутентификации peer?', 'Запрашивает пароль', 'Запрашивает у клиента пароль роли', 'Пароль запрашивают методы scram-sha-256, md5 и password.', NULL),
        ('option', 'Как работает метод аутентификации peer?', 'Разрешает подключение без проверок', 'Разрешает подключение без каких-либо проверок', 'Так работает trust.', NULL),
        ('option', 'Как работает метод аутентификации peer?', 'Проверяет клиентский сертификат', 'Проверяет клиентский сертификат роли', 'Так работает cert.', NULL),
        ('option', 'Как работает метод аутентификации peer?', 'Запрашивает имя пользователя у ОС и сравнивает его с именем роли', 'Спрашивает имя пользователя у ОС и сверяет с ролью', 'Работает только для локальных подключений; имя пользователя ОС можно сопоставить с ролью через pg_ident.conf.', 'Работает для локальных подключений: имя пользователя ОС сравнивается с именем роли и может быть сопоставлено с ролью через pg_ident.conf.'),
        ('option', 'Какой парольный метод аутентификации рекомендуется использовать?', 'md5', 'Метод md5 из pg_hba.conf', 'Менее надёжен, чем scram-sha-256.', NULL),
        ('option', 'Какой парольный метод аутентификации рекомендуется использовать?', 'password', 'Метод password из pg_hba.conf', 'Передаёт пароль открытым текстом.', NULL),
        ('option', 'Какой парольный метод аутентификации рекомендуется использовать?', 'trust', 'Метод trust из pg_hba.conf', 'Пароль вообще не проверяется.', NULL),
        ('option', 'Какой парольный метод аутентификации рекомендуется использовать?', 'scram-sha-256', 'Метод scram-sha-256 из pg_hba.conf', 'Самый надёжный из парольных методов.', NULL),
        ('option', 'Какие права должны быть у файла ~/.pgpass, чтобы PostgreSQL его использовал?', '644', 'Права 644 — чтение для группы и остальных', 'Файл доступен на чтение другим, его проигнорируют.', NULL),
        ('option', 'Какие права должны быть у файла ~/.pgpass, чтобы PostgreSQL его использовал?', '600 — доступ только владельцу', 'Права 600 — доступ лишь владельцу файла', 'Подходят права без доступа для группы и остальных, например 600 или 400.', NULL),
        ('option', 'Какие права должны быть у файла ~/.pgpass, чтобы PostgreSQL его использовал?', '755', 'Права 755 — доступ для группы и остальных', 'Файл доступен другим, его проигнорируют.', NULL),
        ('option', 'Какие права должны быть у файла ~/.pgpass, чтобы PostgreSQL его использовал?', '777', 'Права 777 — полный доступ всем пользователям', 'Файл доступен всем, его проигнорируют.', NULL),
        ('option', 'Что разрешает привилегия USAGE на схему?', 'Создавать объекты в схеме', 'Создавать объекты внутри схемы', 'Это привилегия CREATE.', NULL),
        ('option', 'Что разрешает привилегия USAGE на схему?', 'Удалять схему', 'Удалять схему вместе с содержимым', 'Удалить схему может её владелец.', NULL),
        ('option', 'Что разрешает привилегия USAGE на схему?', 'Обращаться к объектам в этой схеме', 'Обращаться к объектам этой схемы', 'Без неё объекты схемы не найти по имени.', NULL),
        ('option', 'Что разрешает привилегия USAGE на схему?', 'Создавать временные таблицы', 'Создавать временные таблицы в базе', 'Это привилегия TEMPORARY на базу данных.', NULL),
        ('option', 'Что такое public в контексте ролей?', 'Роль суперпользователя', 'Роль суперпользователя кластера', 'Суперпользователь определяется атрибутом SUPERUSER.', NULL),
        ('option', 'Что такое public в контексте ролей?', 'Псевдороль, неявно включающая все остальные роли', 'Псевдороль, которую неявно имеют все роли', 'Её привилегии получают все роли.', 'Псевдороль, неявно включающая все остальные роли: её привилегии получают все роли.'),
        ('option', 'Что такое public в контексте ролей?', 'Роль владельца базы', 'Роль владельца текущей базы данных', 'Владелец — отдельное понятие.', NULL),
        ('option', 'Что такое public в контексте ролей?', 'Роль для репликации', 'Роль для потоковой репликации', 'Для репликации нужен атрибут REPLICATION (или права суперпользователя).', NULL),
        ('option', 'Какие методы аутентификации запрашивают пароль?', '`scram-sha-256`', 'Метод scram-sha-256 из pg_hba.conf', 'Рекомендуемый парольный метод.', NULL),
        ('option', 'Какие методы аутентификации запрашивают пароль?', '`md5`', 'Метод md5 из pg_hba.conf', 'Тоже запрашивает пароль, но менее надёжен.', NULL),
        ('option', 'Какие методы аутентификации запрашивают пароль?', '`peer`', 'Метод peer из pg_hba.conf', 'Спрашивает имя пользователя у ОС.', NULL),
        ('option', 'Какие методы аутентификации запрашивают пароль?', '`trust`', 'Метод trust из pg_hba.conf', 'Пускает без проверок.', NULL),
        ('option', 'Что верно для владельца объекта?', 'Владельцем может быть только суперпользователь', 'Владельцем может быть суперпользователь кластера', 'Владельцем может быть любая роль.', 'Владельцем может быть любая роль, а не только суперпользователь.'),
        ('option', 'Когда сервер в Linux начинает применять изменения, внесённые в pg_hba.conf?', 'После следующей контрольной точки', 'После следующей контрольной точки сервера', 'Контрольная точка к конфигурации доступа отношения не имеет.', NULL),
        ('option', 'Когда сервер в Linux начинает применять изменения, внесённые в pg_hba.conf?', 'Только после полной остановки и запуска сервера', 'После полной остановки и запуска сервера', 'Перезапуск не нужен, достаточно перечитать конфигурацию.', NULL),
        ('option', 'Когда сервер в Linux начинает применять изменения, внесённые в pg_hba.conf?', 'Сразу после сохранения файла', 'Сразу после сохранения файла на диск', 'Сервер не отслеживает изменения файла сам, его нужно перечитать.', NULL),
        ('option', 'Когда сервер в Linux начинает применять изменения, внесённые в pg_hba.conf?', 'После перечитывания конфигурации, например функцией pg_reload_conf()', 'После перечитывания, например pg_reload_conf()', 'Как и для параметров postgresql.conf, не требующих перезапуска, изменения вступают в силу после перечитывания.', 'Как и для параметров postgresql.conf, не требующих перезапуска, изменения вступают в силу после перечитывания конфигурации, например функцией pg_reload_conf().'),
        ('option', 'Где в кластере хранится хеш пароля роли?', 'В файле postgresql.conf', 'В файле postgresql.conf кластера', 'В нём хранятся параметры конфигурации, пароли ролей там не задаются.', NULL),
        ('option', 'Где в кластере хранится хеш пароля роли?', 'В таблице системного каталога pg_authid', 'В таблице каталога pg_authid', 'Это общая таблица каталога; пароль хранится в виде хеша.', NULL),
        ('option', 'Где в кластере хранится хеш пароля роли?', 'В файле pg_hba.conf', 'В файле pg_hba.conf сервера', 'В нём описаны правила подключения, но не пароли.', NULL),
        ('option', 'Роль bob с атрибутом NOINHERIT включили в роль dba командой GRANT dba TO bob. Как bob может воспользоваться привилегиями dba?', 'Только после смены атрибута LOGIN', 'После смены атрибута LOGIN у роли bob', 'LOGIN определяет возможность подключения, а не наследование.', NULL),
        ('option', 'Роль bob с атрибутом NOINHERIT включили в роль dba командой GRANT dba TO bob. Как bob может воспользоваться привилегиями dba?', 'Никак: роль с NOINHERIT нельзя включать в другие роли', 'Никак: NOINHERIT запрещает включение в роли', 'Включение допускается, меняется лишь способ использования привилегий.', NULL),
        ('option', 'Роль bob с атрибутом NOINHERIT включили в роль dba командой GRANT dba TO bob. Как bob может воспользоваться привилегиями dba?', 'Только после явного переключения командой SET ROLE dba', 'После явного переключения командой SET ROLE dba', 'Автоматически привилегии dba не применяются, а переключение разрешено.', NULL),
        ('option', 'Роль bob с атрибутом NOINHERIT включили в роль dba командой GRANT dba TO bob. Как bob может воспользоваться привилегиями dba?', 'Автоматически, как любая включённая роль', 'Автоматически, как для любой включённой роли', 'Так было бы без NOINHERIT.', NULL),
        ('option', 'Почему недостаточно один раз отозвать у public привилегию EXECUTE на все подпрограммы?', 'После отзыва привилегия возвращается при перезапуске сервера', 'После отзыва привилегия возвращается при перезапуске', 'Перезапуск привилегии не меняет.', NULL),
        ('option', 'Почему недостаточно один раз отозвать у public привилегию EXECUTE на все подпрограммы?', 'Для каждой новой подпрограммы public снова получает EXECUTE автоматически', 'Новые подпрограммы снова получают EXECUTE для public', 'Остановить это можно механизмом привилегий по умолчанию.', 'Для каждой новой подпрограммы public снова получает EXECUTE автоматически; остановить это можно механизмом привилегий по умолчанию.'),
        ('option', 'Какие из перечисленных ролей входят в число предопределённых в PostgreSQL 16?', 'pg_admin', 'Роль pg_admin', 'Такой предопределённой роли нет.', NULL),
        ('option', 'Какие из перечисленных ролей входят в число предопределённых в PostgreSQL 16?', 'pg_superuser', 'Роль pg_superuser', 'Такой предопределённой роли нет; суперпользователь определяется атрибутом SUPERUSER.', NULL),
        ('option', 'Какие из перечисленных ролей входят в число предопределённых в PostgreSQL 16?', 'pg_monitor', 'Роль pg_monitor', 'Роль для мониторинга, объединяет доступ к статистике и параметрам.', NULL),
        ('option', 'Какие из перечисленных ролей входят в число предопределённых в PostgreSQL 16?', 'pg_write_all_data', 'Роль pg_write_all_data', 'Даёт право изменять данные во всех таблицах.', NULL)
    ) AS fixes(kind, question_text, opt_text, new_opt_text, old_text, new_text)
    LOOP
        -- Сначала ровно один вопрос по тексту (прежнему или новому), дальше всё только по его id.
        SELECT count(*), min(id) INTO matches, qid FROM questions
        WHERE question_text IN (fix.question_text, CASE WHEN fix.kind = 'question' THEN fix.new_text ELSE fix.question_text END);
        IF matches <> 1 THEN RAISE EXCEPTION 'Не найден единственный вопрос для исправления'; END IF;
        IF fix.kind = 'question' THEN
            UPDATE questions SET question_text = fix.new_text WHERE id = qid;
        ELSIF fix.kind = 'explanation' THEN
            PERFORM 1 FROM questions WHERE id = qid AND explanation IN (fix.old_text, fix.new_text);
            IF NOT FOUND THEN RAISE EXCEPTION 'Неожиданное пояснение вопроса'; END IF;
            UPDATE questions SET explanation = fix.new_text WHERE id = qid;
        ELSE
            SELECT count(*), min(o.key) INTO matches, k
            FROM questions q, jsonb_each_text(q.options) o
            WHERE q.id = qid AND o.value IN (fix.opt_text, coalesce(fix.new_opt_text, fix.opt_text));
            IF matches <> 1 THEN RAISE EXCEPTION 'Не найден единственный вариант ответа для исправления'; END IF;
            IF fix.new_text IS NOT NULL THEN
                PERFORM 1 FROM questions WHERE id = qid AND option_notes ->> k IN (fix.old_text, fix.new_text);
                IF NOT FOUND THEN RAISE EXCEPTION 'Неожиданное пояснение варианта'; END IF;
                UPDATE questions SET option_notes = jsonb_set(option_notes, ARRAY[k], to_jsonb(fix.new_text)) WHERE id = qid;
            END IF;
            IF fix.new_opt_text IS NOT NULL THEN
                UPDATE questions SET options = jsonb_set(options, ARRAY[k], to_jsonb(fix.new_opt_text)) WHERE id = qid;
            END IF;
        END IF;
    END LOOP;
END
$fix$;

COMMIT;
